bx() { kubectl --context main -n billing-app exec deploy/billing -c app -- "$@" 2>/dev/null; }
check "ConfigMap billing-config: key billing.properties from the file, plus LOG_LEVEL=debug" bash -c "[ \"\$(kubectl --context main -n billing-app get cm billing-config -o jsonpath='{.data.LOG_LEVEL}')\" = debug ] && kubectl --context main -n billing-app get cm billing-config -o jsonpath='{.data.billing\.properties}' | grep -q 'invoice.prefix=INV-2026-'"
check "Secret billing-db is immutable and holds DB_USER/DB_PASSWORD" bash -c "[ \"\$(kubectl --context main -n billing-app get secret billing-db -o jsonpath='{.immutable}')\" = true ] && [ \"\$(kubectl --context main -n billing-app get secret billing-db -o jsonpath='{.data.DB_USER}' | base64 -d)\" = billing ] && [ \"\$(kubectl --context main -n billing-app get secret billing-db -o jsonpath='{.data.DB_PASSWORD}' | base64 -d)\" = 'S3cure!pass' ]"
check "billing's container sees LOG_LEVEL, DB_USER and DB_PASSWORD as env vars" bash -c "$(declare -f bx); deploy_ready main billing billing-app 1 && e=\$(bx env) && echo \"\$e\" | grep -qx LOG_LEVEL=debug && echo \"\$e\" | grep -qx DB_USER=billing && echo \"\$e\" | grep -qx 'DB_PASSWORD=S3cure!pass'"
check "/etc/billing/billing.properties is mounted from the ConfigMap (and nothing else from it in that dir)" bash -c "$(declare -f bx); bx cat /etc/billing/billing.properties | grep -q 'tax.rate=0.20' && [ \"\$(bx ls /etc/billing | tr -d '[:space:]')\" = billing.properties ]"
